async function persist34(path,value){const B='/dev/shm/github-product34-client33-repair';const s=JSON.stringify(value,null,2);const guard=await tools.exec_command({cmd:"python -c 'from pathlib import Path; b=Path(\"/dev/shm/github-product34-client33-repair\"); v=sum(p.lstat().st_blocks*512 for p in [b,*b.rglob(\"*\")]); d=b/\"streaming\"; dv=sum(p.lstat().st_blocks*512 for p in [d,*d.rglob(\"*\")]) if d.exists() else 0; assert dv<=18874368,(dv,\"STOP_STREAM_PHASE_LIMIT\"); remaining=18874368-dv; assert v+"+(s.length+16384)+"+remaining+2097152<=83886080,(v,dv,remaining,2097152,\"STOP_METADATA_RESERVE\")'",max_output_tokens:500});if(guard.exit_code!==0)throw Error(JSON.stringify(guard));const w=await tools.apply_patch("*** Begin Patch\n*** Add File: "+B+"/"+path+"\n+"+s.split("\n").join("\n+")+"\n*** End Patch");if(w.isError)throw Error(JSON.stringify(w));}
async function upload34(plan,planPath,phase,start,end){const B="/dev/shm/github-product34-client33-repair"; const results=load("p34-"+phase+"-uploads")||[];for(let i=start;i<Math.min(end,plan.length);i++){const x=plan[i];let content="";for(let offset=0;offset<x.transport_bytes;offset+=60000){const n=Math.min(60000,x.transport_bytes-offset);const r=await tools.exec_command({cmd:"python "+B+"/canonical_outbound_slice.py --plan "+planPath+" --index "+i+" --offset "+offset+" --count "+n,max_output_tokens:50000,yield_time_ms:30000});if(r.exit_code!==0||r.output.length!==n)throw Error("STOP canonical slice "+JSON.stringify({i,offset,n,actual:r.output.length,r}));content+=r.output;}
if(content.length!==x.transport_bytes)throw Error("transport length");
for(const repo of (x.path.startsWith("critical-parts/")||x.path.startsWith("body-parts/")?["SAMSARA"]:["SAMSARA","Kageyoni"])){
const request={repository_full_name:"guarani-ux/"+repo,encoding:x.encoding,content};const issued={index:i,repo,path:x.path,canonical:x.local,bytes:x.bytes,sha256:x.sha256,git_sha1:x.git_sha1,encoding:x.encoding,transport_bytes:content.length,transport_mode:x.transport_mode,source_retained:true};
await persist34("api-"+phase+"/"+String(i).padStart(3,"0")+"-"+repo+"-issued.json",issued);
const r=await tools.mcp__codex_apps__github_create_blob(request);store("p34-lastmutation",{issued,reply:r});
await persist34("api-"+phase+"/"+String(i).padStart(3,"0")+"-"+repo+"-reply.json",r);
if(r.isError||r.structuredContent?.sha!==x.git_sha1)throw Error("STOP upload unknown/mismatch "+JSON.stringify({issued,reply:r}));
results.push({...x,repo,actual_git_sha1:r.structuredContent.sha});store("p34-"+phase+"-uploads",results);
}
if(i%8===0)notify({phase,index:i,total:plan.length,actual_created_values:results.length});}return {completed:end,total:plan.length,values:results.length};}

